//! Bounded closure of the line permutations induced by verified generators.

use std::collections::HashSet;

/// Order of the permutation group generated by `generators` on `degree`
/// points, or `None` once more than `max_order` elements are reached.
///
/// Each generator lists the image position of every point. Closure is a
/// breadth-first right-multiplication by generators; the group is finite, so
/// the set of products is the generated group.
pub(super) fn permutation_group_order(
    degree: usize,
    generators: &[Box<[usize]>],
    max_order: usize,
) -> Option<usize> {
    let identity: Box<[usize]> = (0..degree).collect();
    let mut seen = HashSet::from([identity.clone()]);
    let mut frontier = vec![identity];
    while let Some(element) = frontier.pop() {
        for generator in generators {
            let product: Box<[usize]> = element.iter().map(|&point| generator[point]).collect();
            if seen.insert(product.clone()) {
                if seen.len() > max_order {
                    return None;
                }
                frontier.push(product);
            }
        }
    }
    Some(seen.len())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn dihedral_square_and_symmetric_five_orders() {
        let rotation: Box<[usize]> = [1, 2, 3, 0].into();
        let reflection: Box<[usize]> = [0, 3, 2, 1].into();
        assert_eq!(
            permutation_group_order(4, &[rotation, reflection], 100),
            Some(8)
        );
        let cycle: Box<[usize]> = [1, 2, 3, 4, 0].into();
        let swap: Box<[usize]> = [1, 0, 2, 3, 4].into();
        assert_eq!(
            permutation_group_order(5, &[cycle.clone(), swap.clone()], 1_000),
            Some(120)
        );
        assert_eq!(permutation_group_order(5, &[cycle, swap], 119), None);
        assert_eq!(permutation_group_order(3, &[], 1), Some(1));
    }
}
